package com.tmevolut.ecommerce.api.controller;
import com.tmevolut.ecommerce.api.dto.*; import com.tmevolut.ecommerce.api.service.CategoriaService; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@Tag(name="Categorias") @RestController @RequestMapping("/api/v1/categorias")
public class CategoriaController { private final CategoriaService service; public CategoriaController(CategoriaService service){this.service=service;}
@GetMapping public Page<CategoriaResponse> listar(Pageable pageable){return service.listar(pageable);} @GetMapping("/{id}") public CategoriaResponse buscar(@PathVariable Long id){return service.buscar(id);} @PostMapping public ResponseEntity<CategoriaResponse> criar(@Valid @RequestBody CategoriaRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.criar(r));} @PutMapping("/{id}") public CategoriaResponse atualizar(@PathVariable Long id,@Valid @RequestBody CategoriaRequest r){return service.atualizar(id,r);} @DeleteMapping("/{id}") public ResponseEntity<Void> remover(@PathVariable Long id){service.remover(id);return ResponseEntity.noContent().build();}}
